/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution 
{
public:
	int SumMaxDepth(TreeNode *root , int mDepth) 
	{
		if(!root)
			return 0 ;
		if(mDepth == 1)
		{
			return root->val ;
		}
		return ( SumMaxDepth(root->left , mDepth-1) + SumMaxDepth(root->right , mDepth-1) ) ;
	}
	int max1(int a , int b)
	{
		return(a>b)?a:b ;
	}
	int maxDepth(TreeNode *root)
	{
		if(!root)
		{
			return 0 ;
		}
		return 1 + max1(maxDepth(root->left),maxDepth(root->right));
	}
    int deepestLeavesSum(TreeNode* root) 
	{
        int mDepth = maxDepth(root) ;
		return SumMaxDepth(root , mDepth) ;
    }
};
